function Count(strings: seq<string>, prefix: string) : int
    requires strings != null
    requires prefix != null
    ensures Count(strings, prefix) == |{s | s in strings && s.StartsWith(prefix}|
{
    var count := 0;
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant count == |{s | s in strings[0..i] && s.StartsWith(prefix}|
